using Microsoft.EntityFrameworkCore;
using Chubb.Claims.Domain.Claims;
using Chubb.Claims.Infrastructure.Persistence;

namespace Chubb.Claims.Infrastructure;

public sealed class ClaimsDbContext(DbContextOptions<ClaimsDbContext> options) : DbContext(options)
{
    public DbSet<MarketRow> Markets => Set<MarketRow>();
    public DbSet<ClaimantProfileRow> ClaimantProfiles => Set<ClaimantProfileRow>();
    public DbSet<StaffProfileRow> StaffProfiles => Set<StaffProfileRow>();
    public DbSet<TeamRow> Teams => Set<TeamRow>();
    public DbSet<TeamMarketRow> TeamMarkets => Set<TeamMarketRow>();
    public DbSet<TeamMembershipRow> TeamMemberships => Set<TeamMembershipRow>();
    public DbSet<ClaimRow> Claims => Set<ClaimRow>();
    public DbSet<MotorClaimDetailsRow> MotorClaimDetails => Set<MotorClaimDetailsRow>();
    public DbSet<PropertyClaimDetailsRow> PropertyClaimDetails => Set<PropertyClaimDetailsRow>();
    public DbSet<ClaimAssignmentRow> ClaimAssignments => Set<ClaimAssignmentRow>();
    public DbSet<ClaimInformationRequestRow> ClaimInformationRequests => Set<ClaimInformationRequestRow>();
    public DbSet<ClaimInformationResponseRow> ClaimInformationResponses => Set<ClaimInformationResponseRow>();
    public DbSet<ClaimDocumentRow> ClaimDocuments => Set<ClaimDocumentRow>();
    public DbSet<ClaimAssessmentRow> ClaimAssessments => Set<ClaimAssessmentRow>();
    public DbSet<ClaimReserveHistoryRow> ClaimReserveHistory => Set<ClaimReserveHistoryRow>();
    public DbSet<ClaimDecisionRow> ClaimDecisions => Set<ClaimDecisionRow>();
    public DbSet<ClaimSettlementRow> ClaimSettlements => Set<ClaimSettlementRow>();
    public DbSet<ClaimActivityRow> ClaimActivities => Set<ClaimActivityRow>();
    public DbSet<ClaimNoteRow> ClaimNotes => Set<ClaimNoteRow>();
    public DbSet<OutboxMessageRow> OutboxMessages => Set<OutboxMessageRow>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.HasDefaultSchema("dbo");
        var market = modelBuilder.Entity<MarketRow>();
        market.ToTable("Markets"); market.HasKey(x => x.MarketCode); market.Property(x => x.MarketCode).HasColumnType("char(3)");
        market.Property(x => x.Name).HasMaxLength(100).IsRequired(); market.Property(x => x.DefaultCurrency).HasColumnType("char(3)"); market.Property(x => x.TimeZoneId).HasMaxLength(100);

        var claimant = modelBuilder.Entity<ClaimantProfileRow>(); claimant.ToTable("ClaimantProfiles"); claimant.HasKey(x => x.SubjectId);
        claimant.Property(x => x.SubjectId).HasMaxLength(200); claimant.Property(x => x.DisplayName).HasMaxLength(200); claimant.Property(x => x.Email).HasMaxLength(320); claimant.Property(x => x.Phone).HasMaxLength(50);
        var staff = modelBuilder.Entity<StaffProfileRow>(); staff.ToTable("StaffProfiles"); staff.HasKey(x => x.SubjectId); staff.Property(x => x.SubjectId).HasMaxLength(200); staff.Property(x => x.DisplayName).HasMaxLength(200);

        var team = modelBuilder.Entity<TeamRow>(); team.ToTable("Teams"); team.HasKey(x => x.TeamId); team.Property(x => x.TeamCode).HasMaxLength(50); team.Property(x => x.Name).HasMaxLength(200); team.HasIndex(x => x.TeamCode).IsUnique();
        var tm = modelBuilder.Entity<TeamMarketRow>(); tm.ToTable("TeamMarkets"); tm.HasKey(x => new { x.TeamId, x.MarketCode }); tm.HasOne(x => x.Team).WithMany().HasForeignKey(x => x.TeamId).OnDelete(DeleteBehavior.Restrict); tm.HasOne(x => x.Market).WithMany().HasForeignKey(x => x.MarketCode).OnDelete(DeleteBehavior.Restrict);
        var membership = modelBuilder.Entity<TeamMembershipRow>(); membership.ToTable("TeamMemberships"); membership.HasKey(x => new { x.TeamId, x.StaffSubjectId, x.EffectiveFromUtc }); membership.Property(x => x.StaffSubjectId).HasMaxLength(200); membership.Property(x => x.AddedBySubjectId).HasMaxLength(200); membership.HasOne(x => x.Team).WithMany().HasForeignKey(x => x.TeamId).OnDelete(DeleteBehavior.Restrict); membership.HasOne(x => x.Staff).WithMany().HasForeignKey(x => x.StaffSubjectId).OnDelete(DeleteBehavior.Restrict); membership.HasIndex(x => new { x.StaffSubjectId, x.EffectiveToUtc, x.TeamId });

        var c = modelBuilder.Entity<ClaimRow>(); c.ToTable("Claims", t => { t.HasCheckConstraint("CK_Claims_LineOfBusiness", "[LineOfBusiness] IN (N'Motor', N'Property')"); t.HasCheckConstraint("CK_Claims_Status", "[Status] IN (N'Submitted', N'InReview', N'Assessment', N'AwaitingInformation', N'Approved', N'Rejected', N'Settled')"); t.HasCheckConstraint("CK_Claims_ReservePair", "([CurrentReserveAmount] IS NULL AND [CurrentReserveCurrency] IS NULL) OR ([CurrentReserveAmount] IS NOT NULL AND [CurrentReserveCurrency] IS NOT NULL AND [CurrentReserveAmount] >= 0)"); });
        c.HasKey(x => x.ClaimId); c.Property(x => x.ClaimNumber).HasMaxLength(32).IsRequired(); c.HasIndex(x => x.ClaimNumber).IsUnique(); c.Property(x => x.ClaimantSubjectId).HasMaxLength(200); c.Property(x => x.ClaimantName).HasMaxLength(200); c.Property(x => x.ClaimantEmail).HasMaxLength(320); c.Property(x => x.ClaimantPhone).HasMaxLength(50); c.Property(x => x.MarketCode).HasColumnType("char(3)"); c.Property(x => x.LineOfBusiness).HasConversion<string>().HasMaxLength(20); c.Property(x => x.PolicyNumber).HasMaxLength(100); c.Property(x => x.Description).HasMaxLength(4000); c.Property(x => x.Status).HasConversion<string>().HasMaxLength(32); c.Property(x => x.CurrentReserveAmount).HasPrecision(19, 4); c.Property(x => x.CurrentReserveCurrency).HasColumnType("char(3)"); c.Property(x => x.RowVersion).IsRowVersion();
        c.HasOne(x => x.Market).WithMany().HasForeignKey(x => x.MarketCode).OnDelete(DeleteBehavior.Restrict); c.HasOne(x => x.Claimant).WithMany().HasForeignKey(x => x.ClaimantSubjectId).OnDelete(DeleteBehavior.Restrict);
        c.HasIndex(x => new { x.ClaimantSubjectId, x.CreatedUtc }).IsDescending(false, true); c.HasIndex(x => new { x.MarketCode, x.Status, x.SubmittedUtc }); c.HasIndex(x => new { x.Status, x.UpdatedUtc }); c.HasIndex(x => new { x.IncidentOccurredUtc, x.MarketCode, x.Status }); c.HasIndex(x => new { x.SubmittedUtc, x.Status, x.MarketCode });
        ConfigureDetails<MotorClaimDetailsRow>(modelBuilder, "MotorClaimDetails"); ConfigureDetails<PropertyClaimDetailsRow>(modelBuilder, "PropertyClaimDetails");
        modelBuilder.Entity<MotorClaimDetailsRow>().HasOne(x => x.Claim).WithOne(x => x.MotorDetails).HasForeignKey<MotorClaimDetailsRow>(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<PropertyClaimDetailsRow>().HasOne(x => x.Claim).WithOne(x => x.PropertyDetails).HasForeignKey<PropertyClaimDetailsRow>(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<MotorClaimDetailsRow>().Property(x => x.VehicleRegistration).HasMaxLength(40); modelBuilder.Entity<MotorClaimDetailsRow>().Property(x => x.Make).HasMaxLength(100); modelBuilder.Entity<MotorClaimDetailsRow>().Property(x => x.Model).HasMaxLength(100); modelBuilder.Entity<MotorClaimDetailsRow>().Property(x => x.VehicleUse).HasMaxLength(80);
        modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.PropertyType).HasMaxLength(80); modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.AddressLine1).HasMaxLength(200); modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.AddressLine2).HasMaxLength(200); modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.City).HasMaxLength(100); modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.Region).HasMaxLength(100); modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.PostalCode).HasMaxLength(30); modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.CountryCode).HasColumnType("char(2)"); modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.LossCause).HasMaxLength(120); modelBuilder.Entity<PropertyClaimDetailsRow>().Property(x => x.AffectedAreaDescription).HasMaxLength(2000);

        var assignment = modelBuilder.Entity<ClaimAssignmentRow>(); assignment.ToTable("ClaimAssignments"); assignment.HasKey(x => x.AssignmentId); assignment.Property(x => x.OfficerSubjectId).HasMaxLength(200); assignment.Property(x => x.AssignedBySubjectId).HasMaxLength(200); assignment.Property(x => x.Reason).HasMaxLength(500); assignment.HasOne(x => x.Claim).WithMany(x => x.Assignments).HasForeignKey(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict); assignment.HasOne(x => x.Team).WithMany().HasForeignKey(x => x.TeamId).OnDelete(DeleteBehavior.Restrict); assignment.HasIndex(x => x.ClaimId).IsUnique().HasFilter("[UnassignedUtc] IS NULL"); assignment.HasIndex(x => new { x.TeamId, x.UnassignedUtc, x.AssignedUtc }); assignment.HasIndex(x => new { x.OfficerSubjectId, x.UnassignedUtc, x.AssignedUtc });
        var request = modelBuilder.Entity<ClaimInformationRequestRow>(); request.ToTable("ClaimInformationRequests", t => t.HasCheckConstraint("CK_ClaimInformationRequests_Status", "[Status] IN (N'Open', N'Responded', N'Cancelled')")); request.HasKey(x => x.RequestId); request.Property(x => x.RequestedBySubjectId).HasMaxLength(200); request.Property(x => x.Question).HasMaxLength(2000); request.Property(x => x.Status).HasMaxLength(20); request.HasOne(x => x.Claim).WithMany(x => x.InformationRequests).HasForeignKey(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict); request.HasIndex(x => new { x.ClaimId, x.Status, x.RequestedUtc });
        var response = modelBuilder.Entity<ClaimInformationResponseRow>(); response.ToTable("ClaimInformationResponses"); response.HasKey(x => x.ResponseId); response.Property(x => x.SubmittedBySubjectId).HasMaxLength(200); response.Property(x => x.ResponseText).HasMaxLength(4000); response.HasOne(x => x.Request).WithMany(x => x.Responses).HasForeignKey(x => x.RequestId).OnDelete(DeleteBehavior.Restrict);
        var document = modelBuilder.Entity<ClaimDocumentRow>(); document.ToTable("ClaimDocuments", t => { t.HasCheckConstraint("CK_ClaimDocuments_LengthBytes", "[LengthBytes] >= 0"); t.HasCheckConstraint("CK_ClaimDocuments_Audience", "[Audience] IN (N'Claimant', N'Staff')"); }); document.HasKey(x => x.DocumentId); document.Property(x => x.UploadedBySubjectId).HasMaxLength(200); document.Property(x => x.Audience).HasMaxLength(20); document.Property(x => x.StorageProvider).HasMaxLength(80); document.Property(x => x.ObjectKey).HasMaxLength(500); document.Property(x => x.OriginalFileName).HasMaxLength(255); document.Property(x => x.ContentType).HasMaxLength(150); document.Property(x => x.Sha256).HasColumnType("char(64)"); document.Property(x => x.UploadStatus).HasMaxLength(30); document.HasOne(x => x.Claim).WithMany(x => x.Documents).HasForeignKey(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict); document.HasOne(x => x.Response).WithMany(x => x.Documents).HasForeignKey(x => x.ResponseId).OnDelete(DeleteBehavior.Restrict); document.HasIndex(x => new { x.ClaimId, x.UploadedUtc });
        var assessment = modelBuilder.Entity<ClaimAssessmentRow>(); assessment.ToTable("ClaimAssessments"); assessment.HasKey(x => x.AssessmentId); assessment.Property(x => x.AssessorSubjectId).HasMaxLength(200); assessment.Property(x => x.AssessmentType).HasMaxLength(40); assessment.Property(x => x.Recommendation).HasMaxLength(40); assessment.Property(x => x.Rationale).HasMaxLength(4000); assessment.HasOne(x => x.Claim).WithMany(x => x.Assessments).HasForeignKey(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict); assessment.HasIndex(x => new { x.ClaimId, x.CreatedUtc });
        var reserve = modelBuilder.Entity<ClaimReserveHistoryRow>(); reserve.ToTable("ClaimReserveHistory", t => t.HasCheckConstraint("CK_ClaimReserveHistory_Amount", "[Amount] >= 0")); reserve.HasKey(x => x.ReserveEntryId); reserve.Property(x => x.Amount).HasPrecision(19, 4); reserve.Property(x => x.Currency).HasColumnType("char(3)"); reserve.Property(x => x.EstimateType).HasMaxLength(40); reserve.Property(x => x.Reason).HasMaxLength(1000); reserve.Property(x => x.RecordedBySubjectId).HasMaxLength(200); reserve.HasOne(x => x.Claim).WithMany(x => x.ReserveHistory).HasForeignKey(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict); reserve.HasIndex(x => new { x.ClaimId, x.RecordedUtc });
        var decision = modelBuilder.Entity<ClaimDecisionRow>(); decision.ToTable("ClaimDecisions", t => { t.HasCheckConstraint("CK_ClaimDecisions_Type", "[DecisionType] IN (N'Approved', N'Rejected')"); t.HasCheckConstraint("CK_ClaimDecisions_AmountPair", "([DecisionAmount] IS NULL AND [DecisionCurrency] IS NULL) OR ([DecisionAmount] IS NOT NULL AND [DecisionCurrency] IS NOT NULL AND [DecisionAmount] >= 0)"); }); decision.HasKey(x => x.DecisionId); decision.HasIndex(x => x.ClaimId).IsUnique(); decision.Property(x => x.DecisionType).HasConversion<string>().HasMaxLength(20); decision.Property(x => x.Reason).HasMaxLength(4000); decision.Property(x => x.DecisionAmount).HasPrecision(19, 4); decision.Property(x => x.DecisionCurrency).HasColumnType("char(3)"); decision.Property(x => x.DecidedBySubjectId).HasMaxLength(200); decision.HasOne(x => x.Claim).WithOne(x => x.Decision).HasForeignKey<ClaimDecisionRow>(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict);
        var settlement = modelBuilder.Entity<ClaimSettlementRow>(); settlement.ToTable("ClaimSettlements", t => { t.HasCheckConstraint("CK_ClaimSettlements_Status", "[Status] IN (N'Pending', N'Completed')"); t.HasCheckConstraint("CK_ClaimSettlements_AmountPair", "([Amount] IS NULL AND [Currency] IS NULL) OR ([Amount] IS NOT NULL AND [Currency] IS NOT NULL AND [Amount] >= 0)"); }); settlement.HasKey(x => x.SettlementId); settlement.HasIndex(x => x.ClaimId).IsUnique(); settlement.Property(x => x.Status).HasMaxLength(20); settlement.Property(x => x.Amount).HasPrecision(19, 4); settlement.Property(x => x.Currency).HasColumnType("char(3)"); settlement.Property(x => x.RecordedBySubjectId).HasMaxLength(200); settlement.Property(x => x.Reference).HasMaxLength(100); settlement.HasOne(x => x.Claim).WithOne(x => x.Settlement).HasForeignKey<ClaimSettlementRow>(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict);
        var activity = modelBuilder.Entity<ClaimActivityRow>(); activity.ToTable("ClaimActivities", t => t.HasCheckConstraint("CK_ClaimActivities_Visibility", "[Visibility] IN (N'Claimant', N'Staff', N'System')")); activity.HasKey(x => x.ActivityId); activity.Property(x => x.ActivityType).HasMaxLength(80); activity.Property(x => x.ActorSubjectId).HasMaxLength(200); activity.Property(x => x.ActorKind).HasMaxLength(20); activity.Property(x => x.Visibility).HasConversion<string>().HasMaxLength(20); activity.Property(x => x.Summary).HasMaxLength(1000); activity.Property(x => x.CorrelationId).HasMaxLength(100); activity.HasOne(x => x.Claim).WithMany(x => x.Activities).HasForeignKey(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict); activity.HasIndex(x => new { x.ClaimId, x.OccurredUtc }); activity.HasIndex(x => new { x.ActivityType, x.OccurredUtc });
        var note = modelBuilder.Entity<ClaimNoteRow>(); note.ToTable("ClaimNotes"); note.HasKey(x => x.NoteId); note.Property(x => x.AuthorSubjectId).HasMaxLength(200); note.Property(x => x.NoteText).HasMaxLength(4000); note.HasOne(x => x.Claim).WithMany(x => x.Notes).HasForeignKey(x => x.ClaimId).OnDelete(DeleteBehavior.Restrict);
        var outbox = modelBuilder.Entity<OutboxMessageRow>(); outbox.ToTable("OutboxMessages", t => { t.HasCheckConstraint("CK_OutboxMessages_AttemptCount", "[AttemptCount] >= 0"); t.HasCheckConstraint("CK_OutboxMessages_EventVersion", "[EventVersion] > 0"); }); outbox.HasKey(x => x.EventId); outbox.Property(x => x.AggregateType).HasMaxLength(100); outbox.Property(x => x.EventType).HasMaxLength(150); outbox.Property(x => x.Payload).HasColumnType("nvarchar(max)"); outbox.Property(x => x.LastError).HasMaxLength(2000); outbox.HasIndex(x => new { x.PublishedUtc, x.NextAttemptUtc, x.CreatedUtc });
    }

    private static void ConfigureDetails<TEntity>(ModelBuilder modelBuilder, string table) where TEntity : class
    {
        var entity = modelBuilder.Entity<TEntity>(); entity.ToTable(table); entity.HasKey("ClaimId");
    }
}
